# Файл сгенерирован автоматически без pyrcc
from PyQt6.QtCore import qRegisterResourceData
import base64

resource_data = {
    'icons/sprites/pencil.png': base64.b64decode(''),
    'icons/sprites/star_empty.png': base64.b64decode(''),
    'icons/sprites/star_full.png': base64.b64decode(''),
    'icons/sprites/trash.png': base64.b64decode(''),
    'icons/sprites/check.png': base64.b64decode(''),
    'icons/sprites/uncheck.png': base64.b64decode(''),
    'icons/sprites/app_icon.ico': base64.b64decode(''),
}

from PyQt6.QtGui import QPixmap, QIcon
_old_qicon_init = QIcon.__init__
def _new_qicon_init(self, *args, **kwargs):
    if args and isinstance(args[0], str) and args[0].startswith(':/'):
        key = args[0].lstrip(':/')
        if key in resource_data:
            pix = QPixmap()
            pix.loadFromData(resource_data[key])
            _old_qicon_init(self, pix)
            return
    _old_qicon_init(self, *args, **kwargs)
QIcon.__init__ = _new_qicon_init
